import json
import math

with open('/root/cycle_margin_analysis.json') as f:
    d=json.load(f)

# schema checks
assert set(d.keys())=={'assumptions','therapies','totals'}
ass=d['assumptions']
assert set(ass.keys())=={'patients_per_therapy','doses_per_day','switch_threshold_usd','model_30_day','model_90_day'}
assert ass['switch_threshold_usd']==12000

ths=d['therapies']
# alphabetical
names=[t['therapy'] for t in ths]
assert names==sorted(names)

# numeric checks: ensure no strings where expecting numbers

def check_number(x):
    return isinstance(x,(int,float)) and not isinstance(x,bool)

for t in ths:
    assert isinstance(t['therapy'],str)
    for k in ['canister_size_units','price_per_1000_doses_usd','packaging_cost_usd','reimbursement_per_fill_240_patients_usd','annual_margin_difference_90_minus_30_usd']:
        assert check_number(t[k]), (t['therapy'],k,type(t[k]))
    for mk in ['30_day','90_day']:
        m=t['models'][mk]
        for k in ['doses_per_fill','fills_per_year','total_annual_doses_per_patient','annual_drug_cost_usd','annual_packaging_cost_usd','annual_reimbursement_usd','annual_margin_usd']:
            assert check_number(m[k]), (t['therapy'],mk,k,type(m[k]))

# decimal places max 2 (allow 1 or 0)

def max2(x):
    s=f"{x}"
    if 'e' in s or 'E' in s:
        # shouldn't happen; treat as fail
        return False
    if '.' not in s:
        return True
    return len(s.split('.')[-1])<=2

for t in ths:
    for k in ['price_per_1000_doses_usd','packaging_cost_usd','reimbursement_per_fill_240_patients_usd','annual_margin_difference_90_minus_30_usd']:
        assert max2(t[k]), (t['therapy'],k,t[k])
    for mk in ['30_day','90_day']:
        m=t['models'][mk]
        for k in ['annual_drug_cost_usd','annual_packaging_cost_usd','annual_reimbursement_usd','annual_margin_usd']:
            assert max2(m[k]), (t['therapy'],mk,k,m[k])

